    h, w = len(grid), len(grid[0])

    # Locate the solid line separating the two panels.
    sep = None
    orientation = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep, orientation = r, "horizontal"
            break
    if sep is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                sep, orientation = c, "vertical"
                break

    if orientation == "horizontal":
        first, second = grid[:sep], grid[sep + 1:]
        n = min(len(first), len(second))
        first, second = first[:n], second[:n]
    else:
        first = [row[:sep] for row in grid]
        second = [row[sep + 1:] for row in grid]
        n = min(len(first[0]), len(second[0]))
        first = [row[:n] for row in first]
        second = [row[:n] for row in second]

