def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the uniform separator.
    sep = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep is not None:
        a, b = grid[:sep], grid[sep + 1:]
        n = min(len(a), len(b))
        a, b = a[:n], b[:n]
        orientation = "horizontal"
    else:
        sep = next(c for c in range(w)
                   if all(grid[r][c] == grid[0][c] for r in range(h)))
        a = [row[:sep] for row in grid]
        b = [row[sep + 1:] for row in grid]
        n = min(len(a[0]), len(b[0]))
        a = [row[:n] for row in a]
        b = [row[:n] for row in b]
        orientation = "vertical"

    colors_a = {x for row in a for x in row}
    colors_b = {x for row in b for x in row}
    common = colors_a & colors_b
    background = next(iter(common)) if common else 0

    return [
        [3 if x == background and y == background else background
         for x, y in zip(ra, rb)]
        for ra, rb in zip(a, b)
    ]
